[
  {
    "statement": "In US prairies and similar open habitats, leaving unburned patches during prescribed fires was associated with increases in Karner blue butterfly abundance over 2–3 years.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "Leaving unburned patches during prescribed fires was associated with greater abundance for six of nine specialist butterfly species.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "Karner blue butterflies were confirmed to use all surveyed unburned patches.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "Rotational burning produced mixed outcomes for butterfly populations.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Under rotational burning, butterfly richness and/or abundance were sometimes higher than on unmanaged or annually burned sites.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Butterfly richness and abundance under rotational burning often varied with the time since the last burn.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Butterfly populations were generally higher more than 1–4 years after burning.",
    "citations": [
      "3883"
    ]
  },
  {
