  {
    "statement": "Fritillary butterflies showed variable responses to rotational burning, including lower abundance for some species in some regions.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Regal fritillary abundance was higher in prairies managed on a three-year rotation than in more recently or much longer unburned sites.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Regal fritillary abundance was higher in prairies four years post-burn than in more recently or much longer unburned sites.",
    "citations": [
      "3883"
    ]
  }
]

[
  {
    "statement": "Using warmer lighting, such as red or yellow, rather than other colours is an identified action to mitigate negative impacts on moths.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "Studies reported fewer individual moths and fewer moth species were attracted to yellow, green, white, or red lights than to UV, actinic, blue, or conventional metal halide lights.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "One study found that four moth species spent more time feeding under red lights than under white or green lights.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "The same study found that the four moth species spent less time feeding under red lights than they did in darkness.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "There are other proposed actions for butterflies and moths that currently have no studies evaluating their effects.",
    "citations": []
  },
  {
    "statement": "Restricting the use of polarized light is a proposed action to help butterflies and moths.",
    "citations": [
      "3903"
    ]
  },
  {
    "statement": "Restricting the timing of lighting to conserve natural light regimes is a proposed action.",
    "citations": [
      "3901"
    ]
  },
  {
    "statement": "Using glazing treatments to reduce light spill from inside lit buildings is a proposed action.",
    "citations": [
      "3905"
    ]
  },
  {
    "statement": "Removing or changing turbine lighting to reduce insect attraction is a proposed action.",
    "citations": [
      "3843"
    ]
  }
]

[
  {
    "statement": "Across 16 studies of translocations, many translocated butterfly and moth populations persisted for 2–12 years and increased in abundance.",
