      "3909"
    ]
  },
  {
    "statement": "Some translocated butterfly and moth populations persisted for 1–49 years and colonized new sites.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Some translocated butterfly and moth populations died out within 0–7 years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "One review found that 25% of translocated or released captive-bred populations survived for three or more years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "One review found that 38% of translocated or released captive-bred populations died out within three years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "One review found that only 8% of translocated or released captive-bred populations were known to survive for more than 10 years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Another review reported that large copper butterfly populations survived for up to 38 years but ultimately died out or required further releases.",
