    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Across 13 studies of captive-bred releases, several populations released as eggs, caterpillars, pupae, or adults persisted for 2–28 years and increased.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "Some captive-bred butterfly populations required continued rearing or supplementation to persist and increase.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "Other releases of captive-bred populations died out after 1, 2, or 12 years.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "Some releases of captive-bred populations required further releases to continue.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "A replicated study found that three out of ten barberry carpet moth releases established populations.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "At least one established population of barberry carpet moths persisted for five years.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "A review across the UK and Ireland reported that 25% of captive-bred or translocated populations survived for more than 3 years.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "A review across the UK and Ireland reported that 38% of captive-bred or translocated populations died within three years.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "A review across the UK and Ireland reported that only 8% of captive-bred or translocated populations were known to survive for more than 10 years.",
    "citations": [
      "3914"
    ]
  },
  {
    "statement": "Released captive-bred large copper caterpillars had lower survival than captive, wild, or translocated caterpillars.",
    "citations": [
      "3914"
    ]
  }
